const $=(s,c=document)=>c.querySelector(s);const $$=(s,c=document)=>[...c.querySelectorAll(s)];
const months=['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];
const days=['воскресенье','понедельник','вторник','среда','четверг','пятница','суббота'];
const now=new Date();$('#current-date').textContent=`${days[now.getDay()]}, ${now.getDate()} ${months[now.getMonth()]}`;
function showView(id){$$('.view').forEach(v=>v.classList.toggle('active',v.id===id));$$('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===id));scrollTo({top:0,behavior:'smooth'})}
$$('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));$('[data-action="profile"]').onclick=()=>showView('profile');
const modal=$('#modal'),content=$('#modal-content');$('.modal-close').onclick=()=>modal.close();
const flowCopy={
 natal:{k:'НАТАЛЬНАЯ КАРТА',n:'Солнце в Водолее',v:'☉',p:'Независимое мышление сочетается у тебя с сильной потребностью находить смысл и создавать системы. Твоя карта подчёркивает ценность свободы, но близкие отношения требуют честно проговаривать границы.',tags:['Солнце · Водолей','Луна · Весы','Асцендент · Скорпион']},
 matrix:{k:'МАТРИЦА СУДЬБЫ',n:'Твой центр — 10 аркан',v:'10',p:'Твоя ключевая тема — видеть возможности в переменах и превращать хаос в направление. Сильная сторона — адаптивность; задача — не отдавать решения на волю обстоятельств.',tags:['Характер · 3','Предназначение · 11','Ресурс · 19']},
 couple:{k:'СОВМЕСТИМОСТЬ',n:'Энергия пары — 6 аркан',v:'6',p:'Центральная тема этой связи — осознанный выбор друг друга. Притяжение усиливается общими решениями, а напряжение возникает, когда третьи лица становятся важнее договорённостей пары.',tags:['Чувства · 14','Быт · 8','Деньги · 17']}
};
function openResult(o){content.innerHTML=`<div class="result-copy"><div class="eyebrow">${o.k}</div><div class="result-wheel"><span>${o.v}</span></div><h2>${o.n}</h2><div class="result-tags">${o.tags.map(x=>`<span>${x}</span>`).join('')}</div><p>${o.p}</p><button class="primary-btn" onclick="document.querySelector('#modal').close()">Понятно</button></div>`;modal.showModal()}
const apiBase=(window.ORBITA_API_URL||'').replace(/\/$/,'');
const planetNames={Sun:'Солнце',Moon:'Луна',Mercury:'Меркурий',Venus:'Венера',Mars:'Марс',Jupiter:'Юпитер',Saturn:'Сатурн',Uranus:'Уран',Neptune:'Нептун',Pluto:'Плутон','True Node':'Северный узел'};
const signNames={Aries:'Овен',Taurus:'Телец',Gemini:'Близнецы',Cancer:'Рак',Leo:'Лев',Virgo:'Дева',Libra:'Весы',Scorpio:'Скорпион',Sagittarius:'Стрелец',Capricorn:'Козерог',Aquarius:'Водолей',Pisces:'Рыбы'};
function zodiac(longitude){const signs=['Овен','Телец','Близнецы','Рак','Лев','Дева','Весы','Скорпион','Стрелец','Козерог','Водолей','Рыбы'];return `${(longitude%30).toFixed(1)}° ${signs[Math.floor((longitude%360)/30)]}`}
function toast(t){const x=$('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2200)}
const readProfile=()=>JSON.parse(localStorage.getItem('orbita-profile')||'null');
const profileComplete=p=>p&&p.birthdate&&p.birthtime&&p.timezone&&p.latitude&&p.longitude;
function dateInZone(zone){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=t=>parts.find(x=>x.type===t).value;return `${get('year')}-${get('month')}-${get('day')}`}
function profileSignature(p){return [p.birthdate,p.birthtime,p.timezone,p.latitude,p.longitude].join('|')}
function chartRequest(p){return {birth_datetime:`${p.birthdate}T${p.birthtime}:00`,timezone:p.timezone,latitude:Number(p.latitude),longitude:Number(p.longitude),house_system:'P'}}
let currentChart=null,currentForecastKey='';
async function loadChart(profile,force=false){const key=`orbita-chart:v3:${dateInZone(profile.timezone)}:${profileSignature(profile)}`;if(!force){const cached=localStorage.getItem(key);if(cached)return JSON.parse(cached)}const response=await fetch(`${apiBase}/v1/natal-chart`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(chartRequest(profile))});const payload=await response.json();if(!response.ok)throw new Error(payload.detail||'Ошибка расчёта');localStorage.setItem(key,JSON.stringify(payload));return payload}
function bindPlaceSearch(form,query,results,state){let timer;query.oninput=()=>{clearTimeout(timer);form.elements.latitude.value='';form.elements.longitude.value='';form.elements.timezone.value='';results.replaceChildren();const value=query.value.trim();if(value.length<2)return;timer=setTimeout(async()=>{state.textContent='Ищем место…';try{const response=await fetch(`${apiBase}/v1/places/search?q=${encodeURIComponent(value)}`);if(!response.ok)throw new Error();const places=await response.json();state.textContent=places.length?'Выберите место из списка':'Ничего не найдено';results.replaceChildren(...places.map(place=>{const button=document.createElement('button');button.type='button';button.textContent=place.label;button.onclick=()=>{query.value=place.label;form.elements.latitude.value=place.latitude;form.elements.longitude.value=place.longitude;form.elements.timezone.value=place.timezone;results.replaceChildren();state.textContent=`Часовой пояс: ${place.timezone}`};return button}))}catch{state.textContent='Не удалось выполнить поиск. Попробуйте ещё раз.'}},350)}}
async function openNatal(){const profile=readProfile();if(!profileComplete(profile)){content.innerHTML=`<div class="result-copy"><div class="eyebrow">НАТАЛЬНАЯ КАРТА</div><h2>Сначала заполни профиль</h2><p>Дата, точное время и место рождения сохраняются один раз и используются для карты и ежедневного прогноза.</p><button class="primary-btn" id="go-profile">Перейти в профиль</button></div>`;modal.showModal();$('#go-profile').onclick=()=>{modal.close();showView('profile')};return}content.innerHTML=`<div class="loading-card"><span>✦</span><h2>Открываем твою карту</h2><p>Проверяем сохранённый расчёт…</p></div>`;modal.showModal();try{currentChart=await loadChart(profile);renderNatal(currentChart)}catch(error){content.innerHTML=`<div class="result-copy"><h2>Не удалось загрузить карту</h2><p>${error.message}</p></div>`}}
function renderNatal(chart){const interpretation=chart.interpretation||{};const cards=(interpretation.cards||[]).map((card,index)=>`<details class="reading-card" ${index===0?'open':''}><summary><span><small>${card.title}</small><strong>${card.summary}</strong></span><b>＋</b></summary><p>${card.body}</p></details>`).join('');content.innerHTML=`<div class="result-copy natal-result"><div class="eyebrow">НАТАЛЬНАЯ КАРТА · SWISS EPHEMERIS</div><div class="result-wheel"><span>☉</span></div><h2>${zodiac(chart.angles.ascendant)} — Асцендент</h2><div class="result-tags"><span>ASC · ${zodiac(chart.angles.ascendant)}</span><span>MC · ${zodiac(chart.angles.midheaven)}</span></div><section class="reading-intro"><h3>${interpretation.headline||'Основные темы карты'}</h3><p>${interpretation.social_style||''}</p></section><div class="reading-cards">${cards}</div><p><small>Астрономические данные рассчитаны Swiss Ephemeris. Текст — символическая интерпретация, а не научный вывод.</small></p><button class="primary-btn" onclick="document.querySelector('#modal').close()">Готово</button></div>`}
function renderForecastModal(forecast){const overview=forecast.overview||{};content.innerHTML=`<div class="result-copy forecast-modal"><div class="eyebrow">ПРОГНОЗ · ${forecast.date}</div><h2>Подробнее о сегодняшнем дне</h2><div class="forecast-detail"><article><strong>Что может проявиться</strong><p>${overview.what_to_expect||forecast.summary}</p></article><article><strong>Для чего день благоприятен</strong><p>${overview.favorable||''}</p></article><article><strong>Чего лучше избегать</strong><p>${overview.avoid||''}</p></article></div><p class="forecast-note"><small>Прогноз описывает символический фон текущих транзитов, а не гарантированные события.</small></p></div>`;modal.showModal()}
function renderSphere(key){const forecast=currentChart?.daily_forecast,sphere=forecast?.spheres?.[key];if(!sphere)return;const names={relationships:'Отношения',work:'Работа',energy:'Энергия'},icons={relationships:'♡',work:'◇',energy:'ϟ'};content.innerHTML=`<div class="result-copy sphere-popup"><div class="eyebrow">СФЕРА ДНЯ · ${forecast.date}</div><div class="result-wheel"><span>${icons[key]}</span></div><h2>${names[key]}</h2><div class="sphere-score">${sphere.score}/10</div><p>${sphere.summary}</p><div class="do-dont"><div><strong>Благоприятно</strong>${sphere.favorable}</div><div><strong>Осторожнее</strong>${sphere.avoid}</div></div><p><small>Оценка отражает текущие транзиты к натальной карте, а не качество самой сферы жизни.</small></p></div>`;modal.showModal()}
function paintToday(forecast){const scores=forecast.scores,overview=forecast.overview||{},key=forecast.key_transit||{};$('#forecast-date').textContent=forecast.date;$('#forecast-headline').textContent=forecast.headline;$('#forecast-summary').textContent=overview.what_to_expect||forecast.summary;['relationships','work','energy'].forEach(name=>{$(`#score-${name}`).textContent=scores[name];$(`#bar-${name}`).style.setProperty('--score',`${scores[name]*10}%`)});$('#transit-title').textContent=key.title||'Спокойный транзитный фон';$('#forecast-advice').textContent=key.explanation||'';$('#transit-practical').textContent=key.advice||'Сохраняй привычный ритм и заверши начатое.'}
async function refreshToday(force=false){const profile=readProfile();if(!profileComplete(profile))return;const key=dateInZone(profile.timezone);if(!force&&currentForecastKey===key)return;currentForecastKey=key;$('#forecast-headline').textContent='Считаем транзиты дня…';try{currentChart=await loadChart(profile,force);paintToday(currentChart.daily_forecast)}catch{$('#forecast-headline').textContent='Прогноз временно недоступен';$('#forecast-summary').textContent='Проверь подключение и попробуй обновить страницу.'}}
$$('[data-flow]').forEach(b=>b.onclick=()=>b.dataset.flow==='natal'?openNatal():openResult(flowCopy[b.dataset.flow]));
$('[data-modal="forecast"]').onclick=async()=>{const profile=readProfile();if(!profileComplete(profile)){showView('profile');return}if(!currentChart)currentChart=await loadChart(profile);renderForecastModal(currentChart.daily_forecast)};
$$('[data-sphere]').forEach(button=>button.onclick=async()=>{const profile=readProfile();if(!profileComplete(profile)){showView('profile');return}if(!currentChart)currentChart=await loadChart(profile);renderSphere(button.dataset.sphere)});
const profileForm=$('#profile-form'),profileQuery=$('#profile-place-query');bindPlaceSearch(profileForm,profileQuery,$('#profile-place-results'),$('#profile-place-state'));
profileForm.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));if(!profileComplete(d)){toast('Выбери место из списка');return}localStorage.setItem('orbita-profile',JSON.stringify(d));currentForecastKey='';currentChart=null;$('#today-title').textContent=d.name||'Алекс';toast('Профиль сохранён');refreshToday(true)};
const saved=readProfile();if(saved){Object.entries(saved).forEach(([k,v])=>{const el=profileForm.elements[k];if(el)el.value=v});$('#today-title').textContent=saved.name||'Алекс';if(saved.timezone)$('#profile-place-state').textContent=`Часовой пояс: ${saved.timezone}`}
refreshToday();setInterval(()=>refreshToday(),60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshToday()});
$('#dream-form').onsubmit=e=>{e.preventDefault();const t=$('#dream-text').value.trim();if(!t)return;content.innerHTML=`<div class="result-copy"><div class="eyebrow">ИНТЕРПРЕТАЦИЯ СНА</div><div class="result-wheel"><span>☾</span></div><h2>Сон о переходе</h2><div class="result-tags"><span>Перемены</span><span>Скрытые эмоции</span><span>Поиск опоры</span></div><p>Образ сна может говорить о ситуации, в которой ты чувствуешь неопределённость, но уже готов двигаться дальше. Обрати внимание не только на символы, но и на главное чувство после пробуждения — оно часто точнее любого «сонника».</p><p><small>Это символическая интерпретация, а не предсказание или диагноз.</small></p></div>`;modal.showModal();const item=document.createElement('button');item.className='dream-item';item.innerHTML=`<span>✨</span><div><small>Сегодня</small><strong>${t.slice(0,36)}${t.length>36?'…':''}</strong><p>Новая запись · AI-разбор</p></div><b>→</b>`;$('#dream-list').prepend(item);$('#dream-count').textContent='3 записи';$('#dream-text').value=''};
const replies=['Сегодня лучше опираться на факты и не принимать сильную эмоцию за окончательный вывод. Если решение можно отложить до вечера — дай себе эту паузу.','В твоём контексте повторяющийся образ часто связан не с внешним предсказанием, а с внутренней потребностью в безопасности и ясных границах.','Завтра подходит для встречи, если цель — спокойный разговор. Сложные темы лучше формулировать через свои чувства и конкретные просьбы.'];
function ask(text){if(!text.trim())return;const chat=$('#chat');chat.insertAdjacentHTML('beforeend',`<div class="message user">${text.replace(/[<>]/g,'')}</div>`);setTimeout(()=>{chat.insertAdjacentHTML('beforeend',`<div class="message bot">${replies[Math.floor(Math.random()*replies.length)]}</div>`);scrollTo({top:document.body.scrollHeight,behavior:'smooth'})},450)}
$('#chat-form').onsubmit=e=>{e.preventDefault();ask($('#chat-input').value);$('#chat-input').value=''};$$('.suggestions button').forEach(b=>b.onclick=()=>ask(b.textContent));
$('[data-action="notifications"]').onclick=()=>toast('Утренний прогноз включён');
